sealed class FixtureHandler(HttpStatusCode code,string body):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellationToken)=>Task.FromResult(new HttpResponseMessage(code){Content=new StringContent(body,Encoding.UTF8,"text/event-stream")});}
